package com.therighthon.rnr.common.block;
import com.therighthon.rnr.common.RNRTags; import net.minecraft.core.BlockPos; import net.minecraft.server.level.ServerLevel; import net.minecraft.util.RandomSource; import net.minecraft.world.level.Level; import net.minecraft.world.level.block.Block; import net.minecraft.world.level.block.Blocks; import net.minecraft.world.level.block.state.BlockState; import net.minecraft.world.level.block.state.StateDefinition; import net.minecraft.world.level.block.state.properties.IntegerProperty;
public class PouringConcretePathBlock extends PathHeightBlock { private static final float defaultSpeedFactor=.7f; public static final IntegerProperty CONCRETE_LEVEL=RNRBlockStateProperties.CONCRETE_LEVEL; public PouringConcretePathBlock(Properties p){super(p.speedFactor(defaultSpeedFactor));registerDefaultState(defaultBlockState().setValue(CONCRETE_LEVEL,3));} public static float getDefaultSpeedFactor(){return defaultSpeedFactor;} protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(CONCRETE_LEVEL);} public void onPlace(BlockState s,Level l,BlockPos p,BlockState old,boolean moving){l.scheduleTick(p,this,10);} public void tick(BlockState s,ServerLevel l,BlockPos p,RandomSource r){int n=s.getValue(CONCRETE_LEVEL);if(n>0)for(net.minecraft.core.Direction d:net.minecraft.core.Direction.Plane.HORIZONTAL)spread(l,p.relative(d),n);l.setBlock(p,RNRBlocks.WET_CONCRETE_ROAD.get().defaultBlockState(),3);} private void spread(Level l,BlockPos p,int n){if(n>0&&l.getBlockState(p).is(RNRTags.Blocks.CONCRETE_SPREADABLE))l.setBlock(p,RNRBlocks.POURING_CONCRETE_ROAD.get().defaultBlockState().setValue(CONCRETE_LEVEL,n-1),3);} }
